#!/usr/bin/env python3
"""Publish the current offline stage and reconcile the existing resource map."""
from pathlib import Path
import json
OUT=Path(__file__).resolve().parents[1];R=OUT/'neoui_reports'
def main():
 b=json.loads((R/'VERIFIED_VEHICLE_NAV_BUILD.json').read_text());e=json.loads((R/'VEHICLE_NAV_RESOURCE_EVIDENCE.json').read_text())
 changes={x['mcf_id']:x for x in b['entries']}
 p=R/'resource_map.json';m=json.loads(p.read_text());m['schema_version']=5;m['status']='46 verified offline records; vehicle/nav compiled bindings added; not car-tested'
 for item in m['entries']:
  resolved=item.get('resolved',[]);ids={r.get('mcf_id') for r in resolved};item['implemented']=bool(ids&changes.keys())
  if item['implemented']:item['scope']='Versioned skin3 fallback. See VERIFIED_VEHICLE_NAV_BUILD.json for exact resource/hash/state evidence.'
 existing={x.get('symbol_id',x.get('logical_id')) for x in m['entries']}
 for entry in b['entries']:
  for logical in entry.get('logical_ids',[entry.get('logical_id')]):
   if logical in existing:continue
   aliases=[a for a in entry['aliases'] if a['logical_id']==logical]
   m['entries'].append(dict(symbol_id=logical,symbol=aliases[0]['symbol'],screen=entry.get('screen','Media transport'),resolved=aliases,implemented=True,screen_confidence=entry['confidence'],scope=b['shared_scope']));existing.add(logical)
 p.write_text(json.dumps(m,indent=2),encoding='utf-8')
 scenarios=R/'scenario_resource_matrix.json';s=json.loads(scenarios.read_text());s['status']='46-record candidate: media + HOME/SETUP + 26 compiled-bound vehicle/navigation graphics; offline component previews'
 for scenario in s['scenarios']:
  prefix=scenario['photo'][:2]
  scenario['current_candidate']='NeoUI_v3_VEHICLE_NAV_skin3.mcf'
  scenario['current_stage_scope']='Shared skin3 action-control changes can appear here; prior screen-specific stage retained.'
  if prefix in ['04','05']:
   relevant=[x for x in b['entries'] if x['mcf_id'] in b['new_vehicle_nav_records'] and (prefix=='05' or x['mcf_id'] not in set(range(1647,1653))|{2221,1024})]
   scenario['implemented_vehicle_nav_mcf_records']=[x['mcf_id'] for x in relevant]
   scenario['mapping_confidence']='Exact static compiled-view -> image array/direct image -> images.res -> MCF for implemented controls; no head-unit execution.'
   scenario['current_stage_scope']='NAVIGATION bottom action controls; map/POIs/routes untouched.' if prefix=='04' else 'Trip-road decoration, 120px paging arrows and action controls; shared car, eco/fuel/safety illustrations untouched.'
   scenario['missing']='Exact composed head-unit coordinates and runtime screenshot confirmation; dynamic state/color execution untested.' if prefix=='04' else 'Actual vehicle-coded skin0 illustration selection and remaining vehicle views; composed head-unit confirmation.'
  if prefix=='03':scenario['current_stage_scope']='M.I.B. MENU/foundation remains exact; no new MENU graphics.'
 scenarios.write_text(json.dumps(s,indent=2),encoding='utf-8')
 (R/'CURRENT_STATE.md').write_text('''# NeoUI v3 current state

Current candidate: neoui_build/NeoUI_v3_VEHICLE_NAV_skin3.mcf. It changes 46 records from exact packaged v1: 16 media transport states, 4 HOME/SETUP assets and 26 FAHRZEUG/navigation action-control graphics. See VEHICLE_NAV_BUILD_REPORT.md and VERIFIED_VEHICLE_NAV_BUILD.json.

The new stage resolves compiled Cmc (trip computer), Nmg (guided navigation) and Nmn (unguided navigation) references through image arrays and images.res to MCF IDs. Runtime layering/day-night/ambient evidence from the preceding stage remains applicable. No metadata or compiled code changes.

106 protected M.I.B. MENU/foundation records, including shared backgrounds and complete blue action-bar strips, remain byte-identical to packaged v1. The preceding 208-record MENU/controlbar protection applied to the previous stage only: this stage intentionally updates verified shared controlbar glyphs and five button-state records. Shared skin3 controls can appear in other applications. Six generic 120px paging arrows can appear outside FAHRZEUG.

Independent restoration reproduces exact v1 bytes. All MCF CRCs and all unchanged records pass. Preview: neoui_previews/VEHICLE_NAV_V3_PREVIEW.html (18 state slots, 26 native asset comparisons, all eight references). Component compositions are not captured head-unit output; their label/icon positions are preview placement, not a verified screen-coordinate reconstruction.

Shared skin0 vehicle illustrations, eco/fuel/safety graphics, map engine/roads/POIs/routes and M.I.B. MENU remain unchanged. The trip-computer decorative road is not the navigation map. Further vehicle screens and actual vehicle-coded illustration selection require more evidence.

Workspace access and file creation work. Original firmware/backups remain read-only. Everything generated stays in NeoUI_v3. No commits, network access, SD/vehicle writes or installer. Independent selectable slot remains UNKNOWN on exact firmware; this is a versioned skin3 fallback, not an additional skin. Not car-ready: current-unit hashes, installed metadata, permissions, separate no-write preflight, release review and explicit installation authorization remain required.
''',encoding='utf-8')
 lines=['# FAHRZEUG and navigation action controls — offline build','','26 new graphics, 46 total. Real source assets and compiled bindings; no guessed MCF IDs. This is an existing skin3 fallback. A separately selectable new skin remains UNKNOWN; see SKIN_SLOT_FEASIBILITY.md.','','## Verified mapping','','| Component | Binding | MCF records |','|---|---|---|','| Trip-computer decorative road | Cmc.initWidgets direct logical 2592 | 2221 (1280×170) |','| Next / previous paging | Cmc image arrays 712 / 715, all 18 positions | 1652/1651/1650 and 1649/1648/1647 (120×120) |','| New destination | Nmg/Nmn array 904 → logical 1937/1938 | 989/988 |','| My destinations | array 903 → 1935/1936 | 991/990 |','| POIs action icon | array 905 → 1939 | 987 (not map POI images.cff) |','| View | array 902 → 1933/1934 | 993/992 |','| Media / tuner / TV dynamic branches | arrays 456/457/907 → 994/995/1941 | 1015/1014/985 |','| Announcements / switch map | arrays 908/906 → 1942/1940 | 984/986 |','| Setup / vehicle view | arrays 831/450 → 1752/984 | 1000/1024 |','| Shared button tiles | arrays 114/115/116/118/119/120/123 | 1707/1714/1716/1717/1719 |','','The icon records are 78×52, tile records 182×92. VEHICLE_NAV_RESOURCE_EVIDENCE.json stores exact module, method, ROM offset, method digest, invocation PC, literal ID, all state positions and resolved aliases. getImageArray is an indirection: array2 (start,length) addresses logical references in array3. Equal numeric image/MCF IDs are never assumed. Both navigation modes resolve the same control families. State-slot indices stay verbatim; C04/C06/C07 and named tile variants are recorded without inventing renderer state labels.','','## Actual changes and shared effects','','Neutral icon pixels receive a restrained ice palette; every chromatic icon pixel is preserved, including green POI detail and yellow media notes. Icon silhouettes, alpha, transparent RGB, dimensions, insets and state bindings remain exact. Decorative green paging and button selected/pressed pixels receive ice while retaining their gradients. Normal separator pixels receive the same cool neutral palette. The trip-road decoration is darkened/cooled without changing lane geometry or alpha.','','The five shared button-state records and shared setup/media/tuner/TV/vehicle-view glyphs can appear in other skin3 application bars. The six paging glyphs can appear in other screens. This is not isolated to NAVIGATION/FAHRZEUG, and does not affect other skin directories unless an unverified installation aliases them; no installation is provided. 86px paging variants and unmapped button variants remain unchanged.','','106 protected MENU/foundation records remain byte-identical to v1: all MAIN_MENU aliases, shared car/background foundation and complete blue action-bar layers. This deliberately replaces the previous stage’s broad 208-record guard with a precise MENU/foundation guard and explicitly authorized controlbar targets. M.I.B. MENU tile graphics, perspective/floor and behavior are retained. All records outside the 46-item manifest are exact.','','The vehicle picture uses shared skin0/imageidmap.res: tagged UTF-16 path strings followed by a matching integer ID array, not path ordinals. Twelve encoded Car/Bordcomputer/Car.png paths resolve; the actual vehicle prefix is unverified. All skin0 pictures and metadata are untouched. Eco leaf, fuel station, safety/status graphics are retained. No navigation road/map/POI/CFF/routing files, viewhandler, selector, ambience maps, NVRAM or filesystem images are modified.','','## Validation and preview','','- Source SHA1: '+b['source_sha1']+'.','- Source SHA256: '+b['source_sha256']+'.','- Candidate SHA256: '+b['candidate_sha256']+'.','- Candidate: neoui_build/NeoUI_v3_VEHICLE_NAV_skin3.mcf; '+str(b['record_count'])+' records; all CRCs pass.','- Exactly 26 new / 46 total changed records; dimensions, alpha and transparent pixels exact; chromatic icon pixels preserved.','- Independent recovery reconstructs original offsets using saved original records plus unchanged candidate records. Complete restored v1 SHA256 equals '+b.get('independent_restore_sha256','NOT YET VERIFIED')+'.','- Reproduce: python tools/build_vehicle_nav_v3.py; python tools/verify_restore.py --vehicle-nav; python tools/preview_vehicle_nav.py; python tools/check_vehicle_nav.py; python tools/update_vehicle_nav_reports.py (from NeoUI_v3).','','VEHICLE_NAV_V3_PREVIEW.html has all 18 navigation state positions, dynamic media branch notes, native trip-road/paging/button comparisons, all 26 before/after pairs and eight reference photographs. The navigation row is a source-asset arrangement with illustrative text placement; it does not claim exact head-unit coordinates or runtime tints. Full-strip blue is a shader sample. Browser visual QA is unavailable due local-file URL policy; native PNGs are inspected and local links/script syntax checked separately.','','## Release limitations','','PC-validated only, no on-car test or installer. The source is the exact packaged installed-v1 reference, not a fresh read of the current unit. Installed skin3 metadata must match the traced skin1-derived lineage before release. Off-car restore success is not a boot-recovery guarantee. Current-unit state, permissions, firmware/MU and hash preflight, release review and explicit installation authorization remain required. Original sources are read-only, no SD/vehicle/network operations, all generated derivatives/binaries/previews excluded from Git.']
 (R/'VEHICLE_NAV_BUILD_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
